questionvariables.text:
/* Shared Question Bank Place Value, Rounding and Standard Form PVRS-09
Application task: convert a contextual large quantity to standard form and interpret its magnitude.
Interaction reference: NUMBAS-10751.
The context and diagnostic layer are independently authored. No source wording or mathematical content is copied. */
d1: rand_with_prohib(1,9,[]);
d2: rand_with_prohib(0,9,[]);
d3: rand_with_prohib(1,9,[]);
coefficient: d1 + d2/10 + d3/100;
exponent: rand_with_prohib(5,7,[]);
mantissa_integer: d1*100 + d2*10 + d3;
quantity: mantissa_integer * 10^(exponent-2);
correct_scale_label: if exponent=5 then "hundreds of thousands" elseif exponent=6 then "millions" else "tens of millions";
scale_is_correct: rand_with_prohib(0,1,[]);
wrong_scale_label: if exponent=5 then "millions" elseif exponent=6 then "tens of millions" else "millions";
scale_label: if scale_is_correct=1 then correct_scale_label else wrong_scale_label;
answer_scale: scale_is_correct;
/* Deliberately incorrect magnitude judgement.
This is always distinct from the correct contextual answer, so the misconception branch remains diagnostic for every variant. */
wrong_magnitude_answer: 1-answer_scale;
coefficient_display: float(coefficient);
scale_truth_text: if answer_scale=1 then "correct" else "not correct";
